class VowelCounter:
    _vowels = {'a', 'e', 'i', 'o', 'u'}
    _cache = {}
    _hits = 0
    _misses = 0
    _max_cache_size = 100
    _recent_access_order = []

    def __init__(self):
        self._reset_stats()

    def _reset_stats(self):
        self._hits = 0
        self._misses = 0
        self._cache = {}
        self._recent_access_order = []

    def _is_vowel(self, char):
        return char.lower() in self._vowels

    def _update_cache(self, text, count):
        if len(self._cache) >= self._max_cache_size:
            self._evict_lru()
        self._cache[text] = count
        if text in self._recent_access_order:
            self._recent_access_order.remove(text)
        self._recent_access_order.append(text)

    def _evict_lru(self):
        if self._recent_access_order:
            lru_key = self._recent_access_order.pop(0)
            del self._cache[lru_key]

    def _lookup_cache(self, text):
        if text in self._cache:
            self._hits += 1
            if text in self._recent_access_order:
                self._recent_access_order.remove(text)
            self._recent_access_order.append(text)
            return self._cache[text]
        self._misses += 1
        return None

    def count_vowels(self, text):
        _cached_result = self._lookup_cache(text)
        if _cached_result is not None:
            return _cached_result

        _current_count = 0
        for _char in text:
            if self._is_vowel(_char):
                _current_count += 1

        self._update_cache(text, _current_count)
        return _current_count

    def _get_stats(self):
        return {'hits': self._hits, 'misses': self._misses, 'cache_size': len(self._cache)}

_vowel_counter_instance = VowelCounter()
