class FactorialCalculator:
    def __init__(self):
        self._cache = {0: 1}
        self._max_cached_n = 0
        self._recursion_limit = 1000
        self._call_count = 0
        self._error_message_template = "Input must be a non-negative integer, got {}"
        self._log_history = []
        self._initialized = True

    def _validate_input(self, n):
        if not isinstance(n, int) or n < 0:
            raise ValueError(self._error_message_template.format(type(n).__name__))

    def _log_calculation(self, n, result):
        self._log_history.append(f"Calculated factorial({n}) = {result}")

    def _recursive_factorial(self, n):
        self._call_count += 1
        if n in self._cache:
            return self._cache[n]
        if n == 0:
            return 1

        if n > self._max_cached_n + 1:
            # Fill intermediate values
            self._recursive_factorial(n - 1) 

        result = n * self._recursive_factorial(n - 1)
        self._cache[n] = result
        self._max_cached_n = max(self._max_cached_n, n)
        return result

    def _get_cache_size(self):
        return len(self._cache)

    def calculate_factorial(self, n):
        self._validate_input(n)
        if n > self._recursion_limit:
            raise RecursionError(f"Recursion depth exceeded for n={n}")

        result = self._recursive_factorial(n)
        self._log_calculation(n, result)
        return result

def calculate_factorial(n):
    _calculator = FactorialCalculator()
    return _calculator.calculate_factorial(n)

