class PalindromeChecker:
    def __init__(self):
        self._cache = {}
        self._max_cache_size = 100
        self._case_sensitive = False
        self._alphanumeric_only = True
        self._current_text = ""
        self._processed_text = ""
        self._result = False
        self._counter = 0

    def _clean_text(self, text):
        if self._case_sensitive:
            cleaned = text
        else:
            cleaned = text.lower()

        if self._alphanumeric_only:
            cleaned = ''.join(char for char in cleaned if char.isalnum())
        return cleaned

    def _check_palindrome_logic(self, cleaned_text):
        return cleaned_text == cleaned_text[::-1]

    def _update_cache(self, original_text, result):
        if len(self._cache) >= self._max_cache_size:
            self._cache.pop(next(iter(self._cache)))
        self._cache[original_text] = result
        self._counter += 1

    def _get_from_cache(self, text):
        return self._cache.get(text)

    def _set_current_text(self, text):
        self._current_text = text

    def _process_and_store(self):
        self._processed_text = self._clean_text(self._current_text)
        self._result = self._check_palindrome_logic(self._processed_text)

    def is_palindrome(self, text):
        cached_result = self._get_from_cache(text)
        if cached_result is not None:
            return cached_result

        self._set_current_text(text)
        self._process_and_store()
        self._update_cache(text, self._result)
        return self._result

def is_palindrome(text):
    checker = PalindromeChecker()
    return checker.is_palindrome(text)

