class EvenNumberFilter:
    def __init__(self):
        self._filtered_list = []
        self._input_numbers = []
        self._is_processed = False
        self._last_processed_input = None
        self._count_processed = 0
        self._history = []
        self._version = "1.0"
        self._log_activity("Initialized filter")

    def _log_activity(self, message):
        self._history.append(f"{self._count_processed}: {message}")

    def _reset_state(self):
        self._filtered_list = []
        self._is_processed = False

    def _process_number(self, number):
        if number % 2 == 0:
            self._filtered_list.append(number)

    def _validate_input(self, numbers):
        if not isinstance(numbers, list) or not all(isinstance(n, int) for n in numbers):
            raise ValueError("Input must be a list of integers.")

    def _store_input(self, numbers):
        self._input_numbers = list(numbers)
        self._last_processed_input = tuple(numbers)

    def _execute_filtering(self):
        for number in self._input_numbers:
            self._process_number(number)
        self._is_processed = True
        self._count_processed += 1
        self._log_activity(f"Processed {len(self._input_numbers)} numbers.")

    def filter_even(self, numbers):
        self._reset_state()
        self._validate_input(numbers)
        self._store_input(numbers)
        self._execute_filtering()
        return self._filtered_list

def filter_even(numbers):
    _filter_instance = EvenNumberFilter()
    return _filter_instance.filter_even(numbers)

