class WordFrequencyAnalyzer:
    def __init__(self, _min_word_length=1, _default_separator=' '):
        self._frequencies = {}
        self._punctuation_chars = ".,!?;:\"'()[]{}"
        self._min_length_to_count = _min_word_length
        self._current_text = ""
        self._separator = _default_separator
        self._initialized = True

    def _clean_word(self, word):
        _cleaned = word.strip(self._punctuation_chars).lower()
        return _cleaned

    def _process_text(self):
        _words = self._current_text.split(self._separator)
        for _word in _words:
            _cleaned_word = self._clean_word(_word)
            if len(_cleaned_word) >= self._min_length_to_count:
                self._update_frequency(_cleaned_word)

    def _update_frequency(self, word):
        self._frequencies[word] = self._frequencies.get(word, 0) + 1

    def _reset_state(self):
        self._frequencies = {}
        self._current_text = ""

    def analyze(self, text):
        self._reset_state()
        self._current_text = text
        self._process_text()
        return self._frequencies

def word_frequency(text):
    _analyzer = WordFrequencyAnalyzer()
    _result = _analyzer.analyze(text)
    return _result

