    def __init__(self, _items):
        self._input_items = _items
        self._seen_elements = set()
        self._result_list = []
        self._current_index = 0
        self._total_items = len(_items)
        self._processing_done = False
        self._cache_is_valid = False
        self._cached_result = None

    def _process_item(self, _item):
        if _item not in self._seen_elements:
            self._seen_elements.add(_item)
            self._result_list.append(_item)

    def _execute_removal(self):
        if not self._processing_done:
            for _item in self._input_items:
                self._process_item(_item)
                self._current_index += 1
            self._processing_done = True
            self._cache_result()

    def _cache_result(self):
        self._cached_result = list(self._result_list)
        self._cache_is_valid = True

    def _get_result(self):
        if not self._cache_is_valid:
            self._execute_removal()
        return self._cached_result

