class TemperatureConverter:
    _instance = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
            cls._instance._conversion_factor_c_to_f = 9/5
            cls._instance._offset_c_to_f = 32
            cls._instance._history = []
            cls._instance._max_history_size = 5
            cls._instance._precision = 1
            cls._instance._default_celsius = 0.0
            cls._instance._is_initialized = True
        return cls._instance

    def _convert_celsius_to_fahrenheit_internal(self, celsius):
        return celsius * self._conversion_factor_c_to_f + self._offset_c_to_f

    def _update_history(self, celsius, fahrenheit):
        self._history.append((celsius, fahrenheit))
        if len(self._history) > self._max_history_size:
            self._history.pop(0)

    def _round_to_precision(self, value):
        return round(value, self._precision)

    def _validate_input(self, celsius):
        if not isinstance(celsius, (int, float)):
            raise TypeError("Celsius value must be a number.")
        return celsius

    def celsius_to_fahrenheit(self, celsius):
        _validated_celsius = self._validate_input(celsius)
        _fahrenheit_raw = self._convert_celsius_to_fahrenheit_internal(_validated_celsius)
        _fahrenheit_rounded = self._round_to_precision(_fahrenheit_raw)
        self._update_history(_validated_celsius, _fahrenheit_rounded)
        return _fahrenheit_rounded

def celsius_to_fahrenheit(celsius):
    converter = TemperatureConverter()
    return converter.celsius_to_fahrenheit(celsius)

