class LongestWordFinder:
    def __init__(self):
        self._max_length = 0
        self._longest_word_found = ""
        self._current_word = ""
        self._words_processed = 0
        self._sentence_length = 0
        self._char_index = 0
        self._is_word_char_check = lambda char: char.isalpha()
        self._reset_state()

    def _reset_state(self):
        self._max_length = 0
        self._longest_word_found = ""
        self._current_word = ""
        self._words_processed = 0
        self._sentence_length = 0
        self._char_index = 0

    def _process_char(self, char):
        if self._is_word_char_check(char):
            self._current_word += char
        else:
            self._evaluate_current_word()
            self._current_word = ""

    def _evaluate_current_word(self):
        self._words_processed += 1
        _current_length = len(self._current_word)
        if _current_length > self._max_length:
            self._max_length = _current_length
            self._longest_word_found = self._current_word

    def _finalize_search(self):
        self._evaluate_current_word()
        return self._longest_word_found

    def find_longest_word(self, sentence):
        self._reset_state()
        self._sentence_length = len(sentence)
        for self._char_index, _char in enumerate(sentence):
            self._process_char(_char)
        return self._finalize_search()

def find_longest_word(sentence):
    _finder = LongestWordFinder()
    return _finder.find_longest_word(sentence)

