class FibonacciGenerator:
    def __init__(self):
        self._cache = {0: 0, 1: 1}
        self._max_n_computed = 1
        self._sequence_list = [0, 1] if self._max_n_computed >= 1 else [0] if self._max_n_computed == 0 else []
        self._initialized = True
        self._last_n_requested = None
        self._debug_mode = False

    def _calculate_next_fib(self, k):
        if k not in self._cache:
            self._cache[k] = self._cache[k - 1] + self._cache[k - 2]
        return self._cache[k]

    def _extend_sequence(self, target_n):
        while self._max_n_computed < target_n - 1:
            self._max_n_computed += 1
            self._sequence_list.append(self._calculate_next_fib(self._max_n_computed))
        self._last_n_requested = target_n

    def _get_result_slice(self, n):
        return self._sequence_list[:n]

    def fibonacci_sequence(self, n):
        if not self._initialized:
            raise RuntimeError("Generator not properly initialized.")
        if not isinstance(n, int) or n < 0:
            raise ValueError("n must be a non-negative integer.")
        if n == 0:
            return []

        self._extend_sequence(n)
        return self._get_result_slice(n)

def fibonacci_sequence(n):
    _generator = FibonacciGenerator()
    return _generator.fibonacci_sequence(n)

