        self._base_dict = _initial_dict if _initial_dict is not None else {}
        self._merged_result = {}
        self._history = []
        self._merge_count = 0
        self._is_initialized = True
        self._last_operation_successful = False
        self._current_source = None

    def _update_history(self, op_type, new_dict):
        self._history.append((op_type, new_dict.copy()))
        self._merge_count += 1
        self._last_operation_successful = True

    def _reset_merge_state(self):
        self._merged_result = {}
        self._last_operation_successful = False
        self._current_source = None

    def _perform_merge(self, dict1, dict2):
        _temp_dict = dict1.copy()
        _temp_dict.update(dict2)
        self._merged_result = _temp_dict
        self._update_history("merge", dict2)
        self._current_source = dict2
        return self._merged_result

    def merge_dictionaries(self, dict1, dict2):
        self._reset_merge_state()
        if not isinstance(dict1, dict) or not isinstance(dict2, dict):
            raise TypeError(self._error_message())
        return self._perform_merge(dict1, dict2)

    def _error_message(self):
        return "Both arguments must be dictionaries."

