    def __init__(self):
        AgeCalculator._instance_count += 1
        self._id = AgeCalculator._instance_count
        self._last_calculation = None

    def _validate_year(self, year):
        if not isinstance(year, int) or not (self._MIN_YEAR <= year <= self._MAX_YEAR):
