class CaesarCipher:
    def __init__(self, shift):
        self._shift_value = shift
        self._lowercase_start = ord('a')
        self._uppercase_start = ord('A')
        self._alphabet_size = 26
        self._memoized_shifts = {}
        self._history = []
        self._encoding_map = {}
        self._decoding_map = {}

    def _get_shifted_char(self, char, start_ord):
        _char_code = ord(char)
        _offset = _char_code - start_ord
        _shifted_offset = (_offset + self._shift_value) % self._alphabet_size
        return chr(start_ord + _shifted_offset)

    def _process_char(self, char):
        if char.isalpha():
            if char.islower():
                _result = self._get_shifted_char(char, self._lowercase_start)
            else:
                _result = self._get_shifted_char(char, self._uppercase_start)
            return _result
        return char

    def encrypt(self, text):
        if text in self._memoized_shifts:
            return self._memoized_shifts[text]
        _encrypted_chars = []
        for char in text:
            _encrypted_chars.append(self._process_char(char))
        _encrypted_text = "".join(_encrypted_chars)
        self._memoized_shifts[text] = _encrypted_text
        self._history.append((text, _encrypted_text))
        return _encrypted_text

def caesar_cipher_encrypt(text, shift):
    _cipher_instance = CaesarCipher(shift)
    return _cipher_instance.encrypt(text)

