        self._min_length = 5
        self._at_symbol = '@'
        self._dot_symbol = '.'
        self._cache = {}
        self._error_message = "Invalid email format."
        self._last_checked_email = None

    def _check_length(self, email):
        return len(email) >= self._min_length

    def _find_at_index(self, email):
        return email.find(self._at_symbol)

    def _find_dot_index(self, email):
        return email.rfind(self._dot_symbol)

    def _is_cached(self, email):
        return email in self._cache

    def _store_cache(self, email, result):
        self._cache[email] = result
        self._last_checked_email = email

    def validate_email(self, email):
        if self._is_cached(email):
