        if not self._check_length(email):
            self._store_cache(email, False)
            return False

        _at_index = self._find_at_index(email)
        _dot_index = self._find_dot_index(email)

        _valid_structure = _at_index > 0 and _dot_index > _at_index + 1 and _dot_index < len(email) - 1
        self._store_cache(email, _valid_structure)
        return _valid_structure

