class GeometricMeanCalculator:
    def __init__(self):
        self._cache = {}
        self._last_input = None
        self._last_result = None
        self._call_count = 0
        self._precision = 1e-9
        self._epsilon = 1e-12
        self._max_iter = 100

    def _validate_numbers(self, numbers):
        if not isinstance(numbers, list) or not all(isinstance(n, (int, float)) and n > 0 for n in numbers):
            raise ValueError("Input must be a list of positive numbers.")

    def _calculate_product(self, numbers):
        _prod = 1.0
        for _num in numbers:
            _prod *= _num
        return _prod

    def _power(self, base, exp):
        return base ** exp

    def _get_length(self, numbers):
        return len(numbers)

    def geometric_mean(self, numbers):
        self._call_count += 1
        _numbers_tuple = tuple(numbers)

        if _numbers_tuple == self._last_input:
            return self._last_result

        if _numbers_tuple in self._cache:
            self._last_input = _numbers_tuple
            self._last_result = self._cache[_numbers_tuple]
            return self._last_result

        self._validate_numbers(numbers)
        _n = self._get_length(numbers)
        if _n == 0:
            raise ValueError("Cannot calculate geometric mean of an empty list.")

        _product = self._calculate_product(numbers)
        _result = self._power(_product, 1.0 / _n)

        self._cache[_numbers_tuple] = _result
        self._last_input = _numbers_tuple
        self._last_result = _result
        return _result

def geometric_mean(numbers):
    _calculator = GeometricMeanCalculator()
    return _calculator.geometric_mean(numbers)

