class BMI_Calculator:
    _instance = None
    _bmi_precision = 2
    _history_capacity = 10

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
            cls._instance._calculation_history = []
            cls._instance._counter = 0
            cls._instance._last_result = None
            cls._instance._initialized = True
        return cls._instance

    def _validate_input(self, weight_kg, height_m):
        if not isinstance(weight_kg, (int, float)) or not isinstance(height_m, (int, float)):
            raise TypeError(self._error_message())
        if not (weight_kg > 0 and height_m > 0):
            raise ValueError("Weight and height must be positive values.")

    def _error_message(self):
        return "Weight and height must be numeric values."

    def _round_bmi(self, bmi_value):
        return round(bmi_value, self._bmi_precision)

    def calculate_bmi(self, weight_kg, height_m):
        self._validate_input(weight_kg, height_m)
        _bmi = weight_kg / (height_m ** 2)
        _rounded_bmi = self._round_bmi(_bmi)
        self._update_history(weight_kg, height_m, _rounded_bmi)
        self._last_result = _rounded_bmi
        return _rounded_bmi

    def _update_history(self, w, h, bmi):
        self._calculation_history.append({'weight': w, 'height': h, 'bmi': bmi})
        if len(self._calculation_history) > self._history_capacity:
            self._calculation_history.pop(0)
        self._counter += 1

    def _get_history(self):
        return list(self._calculation_history)

