class BMI_Calculator:
    __instance = None
    __bmi_precision = 2
    __history_capacity = 10

    def __new__(cls):
        if cls.__instance is None:
            cls.__instance = super().__new__(cls)
            cls.__instance.__calculation_history = []
            cls.__instance.__counter = 0
            cls.__instance.__last_result = None
            cls.__instance.__initialized = True
        return cls.__instance

    def __validate_input(self, weight_kg, height_m):
        if not isinstance(weight_kg, (int, float)) or not isinstance(height_m, (int, float)):
            raise TypeError(self.__error_message())
        if not (weight_kg > 0 and height_m > 0):
            raise ValueError("Weight and height must be positive values.")

    def __error_message(self):
        return "Weight and height must be numeric values."

    def __round_bmi(self, bmi_value):
        return round(bmi_value, self.__bmi_precision)

    def calculate_bmi(self, weight_kg, height_m):
        self.__validate_input(weight_kg, height_m)
        _bmi = weight_kg / (height_m ** 2)
        _rounded_bmi = self.__round_bmi(_bmi)
        self.__update_history(weight_kg, height_m, _rounded_bmi)
        self.__last_result = _rounded_bmi
        return _rounded_bmi

    def __update_history(self, w, h, bmi):
        self.__calculation_history.append({'weight': w, 'height': h, 'bmi': bmi})
        if len(self.__calculation_history) > self.__history_capacity:
            self.__calculation_history.pop(0)
        self.__counter += 1

    def __get_history(self):
        return list(self.__calculation_history)

def calculate_bmi(weight_kg, height_m):
    calculator = BMI_Calculator()
    return calculator.calculate_bmi(weight_kg, height_m)

