class QueueSimulator:
    def __init__(self):
        self._queue = []
        self._history = []
        self._max_size = 100
        self._op_count = 0
        self._last_dequeued = None
        self._logger = []
        self._is_initialized = True
        self._current_operation_type = None

    def _enqueue_item(self, item):
        if len(self._queue) < self._max_size:
            self._queue.append(item)
            self._history.append(('enqueue', item))
            self._op_count += 1
            self._logger.append(f"Enqueued: {item}")
        else:
            self._logger.append("Queue full, cannot enqueue.")

    def _dequeue_item(self):
        if self._queue:
            item = self._queue.pop(0)
            self._last_dequeued = item
            self._history.append(('dequeue', item))
            self._op_count += 1
            self._logger.append(f"Dequeued: {item}")
            return item
        else:
            self._logger.append("Queue empty, cannot dequeue.")
            return None

    def _process_operation(self, operation_type, value):
        self._current_operation_type = operation_type
        if operation_type == 'enqueue':
            self._enqueue_item(value)
        elif operation_type == 'dequeue':
            self._dequeue_item()
        self._check_consistency()

    def _get_queue_state(self):
        return list(self._queue)

    def _check_consistency(self):
        if self._op_count > 0 and not self._is_initialized:
            raise ValueError("Simulator not properly initialized for operations.")
        if self._current_operation_type is not None:
            self._logger.append(f"Operation {self._current_operation_type} completed.")

    def _reset_state(self):
        self._queue = []
        self._history = []
        self._op_count = 0
        self._last_dequeued = None
        self._logger = []
        self._is_initialized = True

def simulate_queue(operations):
    _simulator = QueueSimulator()
    for _op_type, _value in operations:
        _simulator._process_operation(_op_type, _value)
    _final_state = _simulator._get_queue_state()
    return _final_state

