import math

class _DistanceCalculator:
    def __init__(self):
        self._last_result = None
        self._last_inputs = None
        self._cache_enabled = True
        self._call_count = 0
        self._hit_count = 0
        self._epsilon = 1e-9 # For floating point comparisons
        self._version = "1.0"
        self._name = "EuclideanDistance"

    def _calculate_squared_diff(self, val1, val2):
        return (val1 - val2) ** 2

    def _check_cache(self, x1, y1, x2, y2):
        if self._cache_enabled and self._last_inputs == (x1, y1, x2, y2):
            self._hit_count += 1
            return self._last_result
        return None

    def _update_cache(self, x1, y1, x2, y2, result):
        if self._cache_enabled:
            self._last_inputs = (x1, y1, x2, y2)
            self._last_result = result

    def _get_epsilon(self):
        return self._epsilon

    def _get_name(self):
        return self._name

    def distance_2d(self, x1, y1, x2, y2):
        self._call_count += 1
        cached_result = self._check_cache(x1, y1, x2, y2)
        if cached_result is not None:
            return cached_result

        dx_sq = self._calculate_squared_diff(x1, x2)
        dy_sq = self._calculate_squared_diff(y1, y2)
        distance = math.sqrt(dx_sq + dy_sq)
        self._update_cache(x1, y1, x2, y2, distance)
        return distance

