class ListOfSquaresGenerator:
    def __init__(self, n):
        self._n = n
        self._cache = None
        self._is_computed = False
        self._data_source = range(1, self._n + 1)
        self._result_list = []
        self._current_index = 0
        self._max_value_reached = False
        self._pre_process()

    def _pre_process(self):
        if self._n < 0:
            raise ValueError("Input must be a non-negative integer.")

    def _compute_square(self, num):
        return num * num

    def _generate_squares(self):
        for i in self._data_source:
            self._result_list.append(self._compute_square(i))
            self._current_index += 1
        self._is_computed = True
        self._max_value_reached = True

    def _get_computed_list(self):
        if not self._is_computed:
            self._generate_squares()
        return self._result_list

    def _check_n_valid(self):
        return self._n >= 0

    def _reset_state(self):
        self._cache = None
        self._is_computed = False
        self._result_list = []
        self._current_index = 0
        self._max_value_reached = False

    def list_of_squares(self):
        if not self._check_n_valid():
            self._reset_state()
            return []
        if self._cache is None or not self._max_value_reached:
            self._cache = self._get_computed_list()
        return self._cache

def list_of_squares(n):
    generator = ListOfSquaresGenerator(n)
    return generator.list_of_squares()

