class GradeCalculator:
    _grade_boundaries = {
        'A': 90,
        'B': 80,
        'C': 70,
        'D': 60,
        'F': 0
    }
    _default_grade = 'F'
    _min_score_allowed = 0
    _max_score_allowed = 100
    _validation_error_message = "Score must be between 0 and 100."

    def __init__(self):
        self._cache = {}
        self._last_calculated_score = None
        self._last_calculated_grade = None

    def _is_valid_score(self, score):
        return self._min_score_allowed <= score <= self._max_score_allowed

    def _get_grade_from_boundaries(self, score):
        for _grade, _boundary in sorted(self._grade_boundaries.items(), key=lambda item: item[1], reverse=True):
            if score >= _boundary:
                return _grade
        return self._default_grade

    def _store_in_cache(self, score, grade):
        self._cache[score] = grade
        self._last_calculated_score = score
        self._last_calculated_grade = grade

    def _retrieve_from_cache(self, score):
        return self._cache.get(score)

    def calculate_grade(self, score):
        if not self._is_valid_score(score):
            raise ValueError(self._validation_error_message)

        _cached_grade = self._retrieve_from_cache(score)
        if _cached_grade:
            return _cached_grade

        _grade_result = self._get_grade_from_boundaries(score)
        self._store_in_cache(score, _grade_result)
        return _grade_result

calculator = GradeCalculator()
calculate_grade = calculator.calculate_grade

