class CsvParser:
    def __init__(self):
        self._delimiter = ','
        self._cache = {}
        self._max_cache_size = 100
        self._cache_hits = 0
        self._cache_misses = 0
        self._internal_count = 0
        self._last_processed_line = None
        self._line_counter = 0

    def _split_string(self, text):
        self._internal_count += 1
        return text.split(self._delimiter)

    def _update_cache(self, line, result):
        if len(self._cache) >= self._max_cache_size:
            self._cache.pop(next(iter(self._cache)))
        self._cache[line] = result

    def _get_from_cache(self, line):
        if line in self._cache:
            self._cache_hits += 1
            return self._cache[line]
        self._cache_misses += 1
        return None

    def _process_line_internal(self, line):
        self._line_counter += 1
        self._last_processed_line = line
        return self._split_string(line)

    def parse_csv_line(self, line):
        _cached_result = self._get_from_cache(line)
        if _cached_result is not None:
            return _cached_result

        _parsed_values = self._process_line_internal(line)
        self._update_cache(line, _parsed_values)
        return _parsed_values

