class PasswordGenerator:
    _lowercase_chars = "abcdefghijklmnopqrstuvwxyz"
    _uppercase_chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    _digit_chars = "0123456789"
    _all_chars = ""
    _min_length = 6
    _max_length = 30
    _cache = {}
    _import_random_module = __import__('random')

    def __init__(self):
        self._initialize_chars()

    def _initialize_chars(self):
        self._all_chars = self._lowercase_chars + self._uppercase_chars + self._digit_chars

    def _validate_length(self, length):
        if not isinstance(length, int) or length < self._min_length or length > self._max_length:
            raise ValueError(f"Password length must be an integer between {self._min_length} and {self._max_length}")

    def _generate_single_char(self):
        return self._import_random_module.choice(self._all_chars)

    def _construct_password(self, length):
        return ''.join(self._generate_single_char() for _ in range(length))

    def _get_from_cache(self, length):
        return self._cache.get(length)

    def _add_to_cache(self, length, password):
        self._cache[length] = password

    def generate_password(self, length):
        self._validate_length(length)
        _cached_password = self._get_from_cache(length)
        if _cached_password:
            return _cached_password
        _password = self._construct_password(length)
        self._add_to_cache(length, _password)
        return _password

