    __lowercase_chars = "abcdefghijklmnopqrstuvwxyz"
    __uppercase_chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    __digit_chars = "0123456789"
    __all_chars = ""
    __min_length = 6
    __max_length = 30
    __cache = {}
    __import_random_module = __import__('random')

    def __init__(self):
        self.__initialize_chars()

    def __initialize_chars(self):
        self.__all_chars = self.__lowercase_chars + self.__uppercase_chars + self.__digit_chars

    def __validate_length(self, length):
        if not isinstance(length, int) or length < self.__min_length or length > self.__max_length:
            raise ValueError(f"Password length must be an integer between {self.__min_length} and {self.__max_length}")

    def __generate_single_char(self):
        return self.__import_random_module.choice(self.__all_chars)

    def __construct_password(self, length):
        return ''.join(self.__generate_single_char() for _ in range(length))

    def __get_from_cache(self, length):
        return self.__cache.get(length)

    def __add_to_cache(self, length, password):
        self.__cache[length] = password

    def generate_password(self, length):
        self.__validate_length(length)
        _cached_password = self.__get_from_cache(length)
        if _cached_password:
            return _cached_password
        _password = self.__construct_password(length)
        self.__add_to_cache(length, _password)
        return _password

_generator = PasswordGenerator()
generate_password = _generator.generate_password

