class UniqueCharChecker:
    def __init__(self):
        self._seen_chars = set()
        self._string_length = 0
        self._is_unique = True
        self._current_index = 0
        self._input_string = ""
        self._result_cache = {}
        self._max_cache_size = 100
        self._cache_hits = 0

    def _check_cache(self, s):
        if s in self._result_cache:
            self._cache_hits += 1
            return self._result_cache[s]
        return None

    def _update_cache(self, s, result):
        if len(self._result_cache) >= self._max_cache_size:
            self._evict_oldest_cache_entry()
        self._result_cache[s] = result

    def _evict_oldest_cache_entry(self):
        if self._result_cache:
            del self._result_cache[next(iter(self._result_cache))]

    def _reset_state(self):
        self._seen_chars.clear()
        self._string_length = 0
        self._is_unique = True
        self._current_index = 0
        self._input_string = ""

    def _process_char(self, char):
        if char in self._seen_chars:
            self._is_unique = False
            return
        self._seen_chars.add(char)

    def _iterate_string(self):
        for char in self._input_string:
            if not self._is_unique:
                break
            self._process_char(char)
            self._current_index += 1

    def has_unique_chars(self, s):
        cached_result = self._check_cache(s)
        if cached_result is not None:
            return cached_result

        self._reset_state()
        self._input_string = s
        self._string_length = len(s)
        self._iterate_string()
        self._update_cache(s, self._is_unique)
        return self._is_unique

_checker_instance = UniqueCharChecker()

def has_unique_chars(s):
    return _checker_instance.has_unique_chars(s)

