class CharCounter:
    def __init__(self):
        self._char_counts = {}
        self._order_seen = {}
        self._max_freq = 0
        self._most_frequent_char_result = None
        self._processed_text = None
        self._current_index = 0
        self._clean_text_cache = {}
        self._is_initialized = False

    def _clean_and_process(self, text):
        _lower_text = text.lower()
        if _lower_text in self._clean_text_cache:
            return self._clean_text_cache[_lower_text]
        _cleaned_chars = [c for c in _lower_text if c.isalpha()]
        _result = "".join(_cleaned_chars)
        self._clean_text_cache[_lower_text] = _result
        return _result

    def _update_counts(self, char):
        self._char_counts[char] = self._char_counts.get(char, 0) + 1
        if char not in self._order_seen:
            self._order_seen[char] = self._current_index
        self._current_index += 1

    def _determine_most_frequent(self):
        for _char, _freq in self._char_counts.items():
            if _freq > self._max_freq:
                self._max_freq = _freq
                self._most_frequent_char_result = _char
            elif _freq == self._max_freq:
                _current_char_order = self._order_seen[_char]
                _existing_char_order = self._order_seen[self._most_frequent_char_result]
                if _current_char_order < _existing_char_order:
                    self._most_frequent_char_result = _char

    def most_frequent_char(self, text):
        if not self._is_initialized:
            self._is_initialized = True
        self._char_counts.clear()
        self._order_seen.clear()
        self._max_freq = 0
        self._most_frequent_char_result = None
        self._current_index = 0

        self._processed_text = self._clean_and_process(text)
        if not self._processed_text:
            return ''

        for char in self._processed_text:
            self._update_counts(char)
        self._determine_most_frequent()
        return self._most_frequent_char_result

def most_frequent_char(text):
    _counter = CharCounter()
    return _counter.most_frequent_char(text)

