class DigitSummer:
    def __init__(self):
        self._cache = {}
        self._last_n = None
        self._last_sum = None
        self._call_count = 0
        self._max_cache_size = 100
        self._debug_mode = False
        self._version = "1.0"
        self._history = []

    def _log_call(self, n, result):
        self._history.append((n, result))
        if self._debug_mode:
            print(f"Logged call: sum_digits({n}) = {result}")

    def _check_n(self, n):
        if not isinstance(n, int) or n < 0:
            raise ValueError("Input must be a non-negative integer.")

    def _get_from_cache(self, n):
        return self._cache.get(n)

    def _add_to_cache(self, n, result):
        if len(self._cache) >= self._max_cache_size:
            self._cache.pop(next(iter(self._cache)))
        self._cache[n] = result

    def _calculate_sum(self, n_str):
        total = 0
        for digit_char in n_str:
            total += int(digit_char)
        return total

    def sum_digits(self, n):
        self._check_n(n)
        self._call_count += 1

        if self._last_n == n:
            self._log_call(n, self._last_sum)
            return self._last_sum

        cached_result = self._get_from_cache(n)
        if cached_result is not None:
            self._last_n = n
            self._last_sum = cached_result
            self._log_call(n, cached_result)
            return cached_result

        n_str = str(n)
        result = self._calculate_sum(n_str)
        self._add_to_cache(n, result)

        self._last_n = n
        self._last_sum = result
        self._log_call(n, result)
        return result

def sum_digits(n):
    _summer_instance = DigitSummer()
    return _summer_instance.sum_digits(n)

