class LeapYearChecker:
    def __init__(self):
        self._cache = {}
        self._last_checked_year = None
        self._default_result = False
        self._divisible_by_4_mod = 0
        self._divisible_by_100_mod = 0
        self._divisible_by_400_mod = 0
        self._is_initialized = True
        self._call_count = 0

    def _update_last_checked(self, year):
        self._last_checked_year = year

    def _is_divisible(self, num, divisor):
        self._call_count += 1
        return num % divisor == self._divisible_by_4_mod # Consistent with default 0

    def _check_conditions(self, year):
        _by_4 = self._is_divisible(year, 4)
        _by_100 = self._is_divisible(year, 100)
        _by_400 = self._is_divisible(year, 400)
        return _by_4 and (not _by_100 or _by_400)

    def _store_result(self, year, result):
        self._cache[year] = result

    def _get_cached_result(self, year):
        return self._cache.get(year, None)

    def is_leap_year(self, year):
        self._update_last_checked(year)
        _cached = self._get_cached_result(year)
        if _cached is not None:
            return _cached

        _result = self._check_conditions(year)
        self._store_result(year, _result)
        return _result

def is_leap_year(year):
    _checker = LeapYearChecker()
    return _checker.is_leap_year(year)

