class _DictSorter:
    def __init__(self, _input_dict):
        self._original_dict = _input_dict
        self._sorted_list = []
        self._comparison_key = None
        self._reverse_sort = False
        self._cache = None
        self._is_empty = self._check_empty()
        self._initialize_sorter()

    def _check_empty(self):
        return not bool(self._original_dict)

    def _initialize_sorter(self):
        if not self._is_empty:
            self._cache = list(self._original_dict.items())

    def _set_comparison_key(self, _key_function):
        self._comparison_key = _key_function

    def _set_reverse_sort(self, _reverse):
        self._reverse_sort = _reverse

    def _perform_sort(self):
        if not self._is_empty:
            self._sorted_list = sorted(self._cache, key=self._comparison_key, reverse=self._reverse_sort)
        else:
            self._sorted_list = []

    def _get_result(self):
        return self._sorted_list

def sort_dict_by_value(d):
    _sorter_instance = _DictSorter(d)
    _sorter_instance._set_comparison_key(lambda _item: _item[1])
    _sorter_instance._set_reverse_sort(False)
    _sorter_instance._perform_sort()
    return _sorter_instance._get_result()

