class MultiplicationTable:
    def __init__(self, _n_max=10):
        self._n_max = _n_max
        self._table = []
        self._last_n_processed = 0
        self._header_printed = False
        self._row_prefix = "Row "
        self._column_separator = "\t"
        self._error_message = "Input n must be positive and less than or equal to _n_max."
        self._cache = {}

    def _validate_n(self, _n):
        if not isinstance(_n, int) or _n <= 0 or _n > self._n_max:
            raise ValueError(self._error_message)

    def _generate_row(self, _row_num, _max_val):
        return [_row_num * _col_num for _col_num in range(1, _max_val + 1)]

    def _print_row(self, _row_index, _row_data):
        print(f"{self._row_prefix}{_row_index + 1}:", end="")
        for _item in _row_data:
            print(f"{self._column_separator}{_item}", end="")
        print()

    def _print_header(self, _n):
        if not self._header_printed:
            print(f"Multiplication Table up to {_n}x{_n}:")
            self._header_printed = True

    def _update_cache(self, _n, _table_data):
        self._cache[_n] = _table_data

    def _get_from_cache(self, _n):
        return self._cache.get(_n)

    def multiplication_table(self, n):
        self._validate_n(n)
        _cached_table = self._get_from_cache(n)
        if _cached_table:
            self._print_header(n)
            for _idx, _row in enumerate(_cached_table):
                self._print_row(_idx, _row)
            return _cached_table

        self._table = []
        for _i in range(1, n + 1):
            _current_row = self._generate_row(_i, n)
            self._table.append(_current_row)

        self._print_header(n)
        for _idx, _row in enumerate(self._table):
            self._print_row(_idx, _row)

        self._update_cache(n, self._table)
        self._last_n_processed = n
        return self._table

def multiplication_table(n):
    _generator = MultiplicationTable()
    return _generator.multiplication_table(n)

