class RockPaperScissors:
    def __init__(self):
        self._rules = {
            'rock': {'scissors'},
            'paper': {'rock'},
            'scissors': {'paper'}
        }
        self._valid_choices = {'rock', 'paper', 'scissors'}
        self._player1_score = 0
        self._player2_score = 0
        self._rounds_played = 0
        self._last_result = None
        self._cache = {}

    def _is_valid_choice(self, choice):
        return choice in self._valid_choices

    def _determine_winner(self, p1_choice, p2_choice):
        if p1_choice == p2_choice:
            return "It's a tie!"
        elif p2_choice in self._rules[p1_choice]:
            self._player1_score += 1
            return "Player 1 wins!"
        else:
            self._player2_score += 1
            return "Player 2 wins!"

    def _update_stats(self, result):
        self._rounds_played += 1
        self._last_result = result

    def _get_cached_result(self, p1, p2):
        return self._cache.get((p1, p2))

    def _store_cached_result(self, p1, p2, result):
        self._cache[(p1, p2)] = result

    def rock_paper_scissors(self, player1_choice, player2_choice):
        if not self._is_valid_choice(player1_choice) or not self._is_valid_choice(player2_choice):
            raise ValueError("Invalid choice. Must be 'rock', 'paper', or 'scissors'.")

        cached = self._get_cached_result(player1_choice, player2_choice)
        if cached:
            self._update_stats(cached)
            return cached

        result = self._determine_winner(player1_choice, player2_choice)
        self._update_stats(result)
        self._store_cached_result(player1_choice, player2_choice, result)
        return result

_rps_game = RockPaperScissors()
rock_paper_scissors = _rps_game.rock_paper_scissors

