        self.__player2_score = 0
        self.__rounds_played = 0
        self.__last_result = None
        self.__cache = {}

    def __is_valid_choice(self, choice):
        return choice in self.__valid_choices

    def __determine_winner(self, p1_choice, p2_choice):
        if p1_choice == p2_choice:
            return "It's a tie!"
        elif p2_choice in self.__rules[p1_choice]:
            self.__player1_score += 1
            return "Player 1 wins!"
        else:
            self.__player2_score += 1
            return "Player 2 wins!"

    def __update_stats(self, result):
        self.__rounds_played += 1
        self.__last_result = result

    def __get_cached_result(self, p1, p2):
        return self.__cache.get((p1, p2))

    def __store_cached_result(self, p1, p2, result):
        self.__cache[(p1, p2)] = result

    def rock_paper_scissors(self, player1_choice, player2_choice):
        if not self.__is_valid_choice(player1_choice) or not self.__is_valid_choice(player2_choice):
            raise ValueError("Invalid choice. Must be 'rock', 'paper', or 'scissors'.")

        cached = self.__get_cached_result(player1_choice, player2_choice)
        if cached:
            self.__update_stats(cached)
            return cached

        result = self.__determine_winner(player1_choice, player2_choice)
        self.__update_stats(result)
        self.__store_cached_result(player1_choice, player2_choice, result)
        return result

