class ListFlattener:
    def __init__(self):
        self._flattened_data = []
        self._current_input = None
        self._processing_index = 0
        self._is_initialized = False
        self._has_errors = False
        self._error_message = ""
        self._cache = {}
        self._result_ready = False

    def _initialize_process(self, list_of_lists):
        self._current_input = list_of_lists
        self._flattened_data = []
        self._processing_index = 0
        self._is_initialized = True
        self._has_errors = False
        self._error_message = ""
        self._result_ready = False

    def _validate_input(self):
        if not isinstance(self._current_input, list):
            self._has_errors = True
            self._error_message = "Input must be a list."
            return False
        return True

    def _process_sublist(self, sublist):
        if not isinstance(sublist, list):
            self._has_errors = True
            self._error_message = "All elements of the main list must be lists."
            return False
        self._flattened_data.extend(sublist)
        return True

    def _perform_flattening(self):
        if not self._validate_input():
            return

        for i, sublist in enumerate(self._current_input):
            self._processing_index = i
            if not self._process_sublist(sublist):
                return
        self._result_ready = True

    def _get_result(self):
        if self._has_errors:
            raise ValueError(self._error_message)
        if not self._result_ready:
            self._perform_flattening()
        return self._flattened_data

    def flatten_list(self, list_of_lists):
        if list_of_lists in self._cache:
            return self._cache[list_of_lists]

        self._initialize_process(list_of_lists)
        self._perform_flattening()

        result = self._get_result()
        self._cache[list_of_lists] = result
        return result

def flatten_list(list_of_lists):
    _flattener_instance = ListFlattener()
    return _flattener_instance.flatten_list(tuple(tuple(sub) for sub in list_of_lists)) # Cache requires hashable input

