class WordReverser:
    def __init__(self, _separator=' '):
        self._separator = _separator
        self._cache = {}
        self._max_cache_size = 10
        self._history = []
        self._debug_mode = False

    def _split_sentence(self, sentence):
        return sentence.split(self._separator)

    def _reverse_list(self, word_list):
        return word_list[::-1]

    def _join_words(self, word_list):
        return self._separator.join(word_list)

    def _update_cache(self, key, value):
        if len(self._cache) >= self._max_cache_size:
            _oldest_key = self._history.pop(0)
            if _oldest_key in self._cache:
                del self._cache[_oldest_key]
        self._cache[key] = value
        self._history.append(key)

    def _log_debug(self, message):
        if self._debug_mode:
            print(f"DEBUG: {message}")

    def reverse_words(self, sentence):
        self._log_debug(f"Reversing sentence: '{sentence}'")
        if not isinstance(sentence, str):
            raise TypeError("Input must be a string.")

        _cleaned_sentence = sentence.strip()
        if not _cleaned_sentence:
            return ""

        if _cleaned_sentence in self._cache:
            self._log_debug("Cache hit.")
            return self._cache[_cleaned_sentence]

        _word_list = self._split_sentence(_cleaned_sentence)
        _reversed_word_list = self._reverse_list(_word_list)
        _result = self._join_words(_reversed_word_list)
        self._update_cache(_cleaned_sentence, _result)
        return _result

def reverse_words(sentence):
    _reverser_instance = WordReverser()
    return _reverser_instance.reverse_words(sentence)

