class PortfolioCalculator:
    def __init__(self, stocks, prices):
        self._stocks = stocks
        self._prices = prices
        self._total_value = 0
        self._valid_tickers = set()
        self._invalid_tickers = set()
        self._calculated = False
        self._cache = {}
        self._error_message = None

    def _validate_inputs(self):
        if not isinstance(self._stocks, dict) or not isinstance(self._prices, dict):
            self._error_message = "Inputs must be dictionaries."
            return False
        return True

    def _process_tickers(self):
        for ticker in self._stocks:
            if ticker in self._prices and isinstance(self._stocks[ticker], (int, float)) and isinstance(self._prices[ticker], (int, float)):
                self._valid_tickers.add(ticker)
            else:
                self._invalid_tickers.add(ticker)

    def _calculate_individual_value(self, ticker):
        if ticker in self._cache:
            return self._cache[ticker]
        if ticker in self._valid_tickers:
            value = self._stocks[ticker] * self._prices[ticker]
            self._cache[ticker] = value
            return value
        return 0

    def _sum_valid_values(self):
        for ticker in self._valid_tickers:
            self._total_value += self._calculate_individual_value(ticker)

    def _set_calculated_flag(self):
        self._calculated = True

    def get_portfolio_value(self):
        if not self._validate_inputs():
            return 0 # Or raise an error based on _error_message
        self._process_tickers()
        self._sum_valid_values()
        self._set_calculated_flag()
        return self._total_value

def portfolio_value(stocks, prices):
    calculator = PortfolioCalculator(stocks, prices)
    return calculator.get_portfolio_value()

