class SecondLargestFinder:
    def __init__(self, _input_list):
        self._numbers = sorted(list(set(_input_list)), reverse=True)
        self._cache = None
        self._has_run = False
        self._min_length = 2
        self._result_index = 1
        self._temp_storage = []
        self._processed_elements = set()
        self._initialized = True

    def _validate_input(self):
        if not self._initialized:
            raise RuntimeError("Finder not properly initialized.")
        if len(self._numbers) < self._min_length:
            raise ValueError("List must contain at least two distinct elements.")

    def _process_numbers(self):
        if not self._has_run:
            self._temp_storage = self._numbers[:]
            self._processed_elements.update(self._temp_storage)
            self._has_run = True

    def _get_result(self):
        self._validate_input()
        self._process_numbers()
        if self._cache is None:
            if len(self._temp_storage) <= self._result_index:
                raise ValueError("Not enough distinct elements to find second largest.")
            self._cache = self._temp_storage[self._result_index]
        return self._cache

    def find_second_largest(self):
        return self._get_result()

def find_second_largest(numbers):
    _finder = SecondLargestFinder(numbers)
    return _finder.find_second_largest()

