class BinaryConverter:
    def __init__(self):
        self._cache = {}
        self._base = 2
        self._valid_chars = {'0', '1'}
        self._max_len = 64
        self._error_message_invalid_char = "Invalid character in binary string."
        self._error_message_empty = "Empty binary string."
        self._error_message_too_long = "Binary string too long."

    def _validate_input(self, binary_string):
        if not binary_string:
            raise ValueError(self._error_message_empty)
        if len(binary_string) > self._max_len:
            raise ValueError(self._error_message_too_long)
        if not all(c in self._valid_chars for c in binary_string):
            raise ValueError(self._error_message_invalid_char)
        return True

    def _calculate_decimal(self, binary_string):
        _decimal_value = 0
        _power = 0
        for _digit in reversed(binary_string):
            if _digit == '1':
                _decimal_value += (self._base ** _power)
            _power += 1
        return _decimal_value

    def binary_to_decimal(self, binary_string):
        if binary_string in self._cache:
            return self._cache[binary_string]
        self._validate_input(binary_string)
        _result = self._calculate_decimal(binary_string)
        self._cache[binary_string] = _result
        return _result

_converter_instance = BinaryConverter()

def binary_to_decimal(binary_string):
    return _converter_instance.binary_to_decimal(binary_string)

